import React from 'react';
import { View, Text, StyleSheet, Platform } from 'react-native';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    // In development, log to console but don't show UI
    if (__DEV__) {
      console.log('Error caught by boundary:', error, errorInfo);
    }
  }

  render() {
    if (this.state.hasError) {
      // In production, show fallback UI
      if (!__DEV__) {
        return (
          <View style={styles.fallback}>
            <Text style={styles.fallbackText}>─É├ú xß║úy ra lß╗ùi</Text>
          </View>
        );
      }
      // In development, render children to allow other errors to show
      return this.props.children;
    }

    return this.props.children;
  }
}

const styles = StyleSheet.create({
  fallback: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#fff',
  },
  fallbackText: {
    fontSize: 16,
    color: '#333',
  },
});

export default ErrorBoundary;

import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, Dimensions, TouchableOpacity } from 'react-native';
import Slider from '@react-native-community/slider';
import * as Haptics from 'expo-haptics';
import { LinearGradient } from 'expo-linear-gradient';
import { DollarSign, Calendar, ArrowRight, MessageSquare } from 'lucide-react-native';
import GlassCard from './GlassCard';
import { useTheme } from '../theme/Theme'; // Import useTheme

const { width } = Dimensions.get('window');

const FinanceCalculator = ({ vehiclePrice = 450000000, onAction }) => {
  const theme = useTheme();
  const [downPaymentPercent, setDownPaymentPercent] = useState(30);
  const [months, setMonths] = useState(24);
  const [monthlyInstallment, setMonthlyInstallment] = useState(0);

  const interestRate = 0.08; // 8% yearly

  useEffect(() => {
    calculateFinance();
  }, [downPaymentPercent, months]);

  const calculateFinance = () => {
    const downPayment = (vehiclePrice * downPaymentPercent) / 100;
    const principal = vehiclePrice - downPayment;

    // Monthly interest rate
    const i = interestRate / 12;
    // Number of months
    const n = months;

    // Standard Amortization Formula: M = P * [ i * (1 + i)^n ] / [ (1 + i)^n ΓÇô 1 ]
    const monthlyPayment = principal * (i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);

    setMonthlyInstallment(Math.round(monthlyPayment));
  };

  const handleSliderChange = (value, setter) => {
    setter(value);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(amount);
  };

  return (
    <View style={getStyles(theme).container}>
      <Text style={getStyles(theme).title}>Dß╗▒ to├ín trß║ú g├│p ≡ƒÆ░</Text>
      <Text style={[getStyles(theme).subtitle, { color: theme.colors.subtext }]}>Gi├í xe: {formatCurrency(vehiclePrice)}</Text>

      <GlassCard style={getStyles(theme).card} intensity={20}>
        <View style={getStyles(theme).row}>
          <Text style={getStyles(theme).label}>Trß║ú tr╞░ß╗¢c ({downPaymentPercent}%)</Text>
          <Text style={getStyles(theme).value}>{formatCurrency((vehiclePrice * downPaymentPercent) / 100)}</Text>
        </View>
        <Slider
          style={getStyles(theme).slider}
          minimumValue={20}
          maximumValue={70}
          step={5}
          value={downPaymentPercent}
          onValueChange={(v) => handleSliderChange(v, setDownPaymentPercent)}
          minimumTrackTintColor={theme.colors.primary}
          maximumTrackTintColor="rgba(255,255,255,0.1)"
          thumbTintColor={theme.colors.primary}
        />

        <View style={[getStyles(theme).row, { marginTop: 20 }]}>
          <Text style={getStyles(theme).label}>Thß╗¥i hß║ín vay</Text>
          <Text style={getStyles(theme).value}>{months} th├íng</Text>
        </View>
        <Slider
          style={getStyles(theme).slider}
          minimumValue={12}
          maximumValue={60}
          step={12}
          value={months}
          onValueChange={(v) => handleSliderChange(v, setMonths)}
          minimumTrackTintColor={theme.colors.secondary}
          maximumTrackTintColor="rgba(255,255,255,0.1)"
          thumbTintColor={theme.colors.secondary}
        />

        <LinearGradient
          colors={['rgba(0,122,255,0.1)', 'rgba(0,122,255,0.05)']}
          style={getStyles(theme).resultBox}
        >
          <Text style={[getStyles(theme).resultLabel, { color: theme.colors.subtext }]}>╞»ß╗¢c t├¡nh trß║ú mß╗ùi th├íng</Text>
          <Text style={[getStyles(theme).resultValue, { color: theme.colors.primary }]}>{formatCurrency(monthlyInstallment)}</Text>
          <Text style={[getStyles(theme).interestHint, { color: theme.colors.success }]}>L├úi suß║Ñt ╞░u ─æ├úi: 8.0%/n─âm</Text>
        </LinearGradient>

        <View style={getStyles(theme).actionRow}>
          <TouchableOpacity
            style={[getStyles(theme).actionBtn, getStyles(theme).secondaryBtn, { borderColor: theme.colors.primary }]}
            onPress={() => onAction?.('chat')}
          >
            <MessageSquare color={theme.colors.primary} size={20} />
            <Text style={[getStyles(theme).secondaryBtnText, { color: theme.colors.primary }]}>T╞░ vß║Ñn</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[getStyles(theme).actionBtn, getStyles(theme).primaryBtn, { backgroundColor: theme.colors.primary }]}
            onPress={() => onAction?.('deposit')}
          >
            <Text style={getStyles(theme).primaryBtnText}>T╞░ Vß║Ñn</Text>
            <ArrowRight color="#FFF" size={20} />
          </TouchableOpacity>
        </View>
      </GlassCard>
    </View>
  );
};
const getStyles = (theme) => StyleSheet.create({
  container: { marginTop: 20 },
  title: { color: theme.colors.text, fontSize: 20, fontWeight: 'bold', marginBottom: 5 },
  subtitle: { color: theme.colors.subtext, fontSize: 14, marginBottom: 20 },
  card: { padding: 20, borderRadius: theme.radius.lg }, // Added borderRadius for consistency
  row: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  label: { color: theme.colors.subtext, fontSize: 13 },
  value: { color: theme.colors.text, fontSize: 15, fontWeight: 'bold' },
  slider: { width: '100%', height: 40, marginTop: 10 },
  resultBox: { marginTop: 25, padding: 20, borderRadius: 16, alignItems: 'center', borderWidth: 1, borderColor: 'rgba(0,122,255,0.2)' },
  resultLabel: { color: theme.colors.subtext, fontSize: 12 },
  resultValue: { color: theme.colors.primary, fontSize: 28, fontWeight: 'bold', marginVertical: 5 },
  interestHint: { color: theme.colors.success, fontSize: 10, fontWeight: 'bold' },
  actionRow: { flexDirection: 'row', marginTop: 25, justifyContent: 'space-between' },
  actionBtn: { height: 50, borderRadius: 12, flexDirection: 'row', alignItems: 'center', justifyContent: 'center' },
  primaryBtn: { flex: 1.5, backgroundColor: theme.colors.primary, marginLeft: 10 },
  secondaryBtn: { flex: 1, borderWidth: 1, borderColor: theme.colors.primary },
  primaryBtnText: { color: '#fff', fontWeight: 'bold', marginRight: 10 },
  secondaryBtnText: { color: theme.colors.primary, fontWeight: 'bold', marginLeft: 10 },
});

export default FinanceCalculator;

import React from 'react';
import { StyleSheet, View } from 'react-native';
import { BlurView } from 'expo-blur';
import { LinearGradient } from 'expo-linear-gradient';
import { Theme, useActiveColors } from '../theme/Theme'; // Keep Theme and useActiveColors
import { useRoute } from '@react-navigation/native';

export default function GlassCard({ children, style, contentStyle, intensity = 20, tint }) {
  const activeColors = useActiveColors();

  const evaluatedTint = tint || (activeColors.isDark ? 'dark' : 'light');

  let isNoFrame = false;
  try {
    const route = useRoute();
    if (route && route.name) {
      const adminRoutes = [
        'AdminDashboard',
        'AdminAppointments',
        'AdminOrders',
        'AdminLeads',
        'AdminHub',
        'AdminProfile',
        'AdminInventory',
        'CashFlow',
        'SupportHub'
      ];
      if (adminRoutes.includes(route.name)) {
        isNoFrame = true;
      }
    }
  } catch (e) {
    // Suppress route context error if rendered outside navigation hierarchy
  }

  const flattened = StyleSheet.flatten(style) || {};
  const layoutStyle = {};
  if (flattened.flexDirection) layoutStyle.flexDirection = flattened.flexDirection;
  if (flattened.alignItems) layoutStyle.alignItems = flattened.alignItems;
  if (flattened.justifyContent) layoutStyle.justifyContent = flattened.justifyContent;
  if (flattened.flexWrap) layoutStyle.flexWrap = flattened.flexWrap;

  if (isNoFrame) {
    return (
      <View style={[styles.borderlessContainer, style]}>
        <View style={[styles.borderlessContent, contentStyle, layoutStyle]}>
          {children}
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.container, { backgroundColor: activeColors.isDark ? 'rgba(30, 41, 59, 0.5)' : 'rgba(255, 255, 255, 0.85)', borderColor: activeColors.isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.05)' }, style]}>
      <BlurView intensity={intensity} tint={tint || (activeColors.isDark ? 'dark' : 'light')} style={StyleSheet.absoluteFill} />
      <LinearGradient
        colors={activeColors.isDark ? ['rgba(255, 255, 255, 0.05)', 'rgba(255, 255, 255, 0)'] : ['rgba(255, 255, 255, 0.6)', 'rgba(255, 255, 255, 0.2)']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <View style={[styles.content, contentStyle, layoutStyle]}>
        {children}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: Theme.radius.lg,
    overflow: 'hidden',
    borderWidth: 1,
  },
  content: {
    padding: Theme.spacing.md,
    width: '100%',
  },
  borderlessContainer: {
    borderRadius: 0,
    borderWidth: 0,
    backgroundColor: 'transparent',
  },
  borderlessContent: {
    paddingVertical: Theme.spacing.sm,
    paddingHorizontal: 0, // Expand content edge-to-edge
    width: '100%',
  },
});

import React, { useState, useEffect } from 'react';
import {
  Modal,
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  Alert,
  Platform,
  ActivityIndicator,
  StyleSheet
} from 'react-native';
import { BlurView } from 'expo-blur';
import { LogOut, Trash2, ChevronRight, Settings, Bell, Shield, Languages, Eye } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { resetRoot, navigationRef } from '../navigation/RootNavigation';
import { useGlobalState } from '../context/GlobalState';
import { useTheme } from '../theme/Theme'; // Import the new useTheme hook
import GlassCard from './GlassCard';

const STORAGE_KEY = '@AEM_Customer_Profile';

export default function GlobalSettingsModal() {
  const { isSettingsOpen, setSettingsOpen, themeMode, setThemeMode } = useGlobalState();
  const theme = useTheme(); // Use the new useTheme hook

  // Local settings state
  const [loading, setLoading] = useState(false);
  const [logoutModalVisible, setLogoutModalVisible] = useState(false);
  const [profileSettings, setProfileSettings] = useState({
    maintenanceNotifications: true,
    biometricLogin: false,
    language: 'vi',
    theme: theme.isDark ? 'dark' : 'light' // Initialize with current theme
  });

  // Haptic feedback
  const triggerHaptic = () => {
    if (Platform.OS !== 'web') {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => { });
    }
  };

  // Load settings when modal is opened
  useEffect(() => {
    if (isSettingsOpen) {
      loadSettings();
    }
  }, [isSettingsOpen]);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const stored = await AsyncStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed && parsed.settings) {
          setProfileSettings({
            maintenanceNotifications: parsed.settings.maintenanceNotifications !== false,
            biometricLogin: !!parsed.settings.biometricLogin,
            language: parsed.settings.language || 'vi',
            theme: parsed.settings.theme || 'dark'
          });
        }
      }
    } catch (err) {
      console.error('[GlobalSettingsModal] Lß╗ùi tß║úi c├ái ─æß║╖t:', err);
    } finally {
      setLoading(false);
    }
  };

  // Save specific settings key
  const handleToggleSetting = async (key, currentValue) => {
    triggerHaptic();
    const newValue = !currentValue;

    // Optimistic state update
    const updatedSettings = {
      ...profileSettings,
      [key]: newValue
    };
    setProfileSettings(updatedSettings);

    try {
      const stored = await AsyncStorage.getItem(STORAGE_KEY);
      let parsed = stored ? JSON.parse(stored) : {};
      parsed.settings = {
        ...(parsed.settings || {}),
        [key]: newValue
      };
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
    } catch (err) {
      console.error('[GlobalSettingsModal] Lß╗ùi l╞░u cß║Ñu h├¼nh:', err);
      Alert.alert('Lß╗ùi', 'Kh├┤ng thß╗â l╞░u c├ái ─æß║╖t.');
      // Rollback
      setProfileSettings(prev => ({ ...prev, [key]: currentValue }));
    }
  };

  // Handle language switch
  const handleLanguageSelect = () => {
    triggerHaptic();
    Alert.alert(
      'Chß╗ìn Ng├┤n Ngß╗» / Select Language',
      'Vui l├▓ng chß╗ìn ng├┤n ngß╗» hiß╗ân thß╗ï:',
      [
        {
          text: 'Tiß║┐ng Viß╗çt ≡ƒç╗≡ƒç│',
          onPress: () => updateSpecificSetting('language', 'vi')
        },
        {
          text: 'English ≡ƒç¼≡ƒçº',
          onPress: () => updateSpecificSetting('language', 'en')
        },
        { text: 'Hß╗ºy / Cancel', style: 'cancel' }
      ]
    );
  };

  // Handle theme toggle between light and dark
  const handleThemeToggle = async () => {
    triggerHaptic();
    const nextTheme = profileSettings.theme === 'dark' ? 'light' : 'dark';

    const updatedSettings = {
      ...profileSettings,
      theme: nextTheme
    };
    setProfileSettings(updatedSettings);
    setThemeMode(nextTheme);

    try {
      const stored = await AsyncStorage.getItem(STORAGE_KEY);
      let parsed = stored ? JSON.parse(stored) : {};
      parsed.settings = {
        ...(parsed.settings || {}),
        theme: nextTheme
      };
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
    } catch (err) {
      console.error('[GlobalSettingsModal] Lß╗ùi l╞░u cß║Ñu h├¼nh theme:', err);
    }
  };

  const updateSpecificSetting = async (key, value) => {
    const updatedSettings = {
      ...profileSettings,
      [key]: value
    };
    setProfileSettings(updatedSettings);

    try {
      const stored = await AsyncStorage.getItem(STORAGE_KEY);
      let parsed = stored ? JSON.parse(stored) : {};
      parsed.settings = {
        ...(parsed.settings || {}),
        [key]: value
      };
      await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
    } catch (err) {
      console.error('[GlobalSettingsModal] Lß╗ùi l╞░u cß║Ñu h├¼nh:', err);
    }
  };

  // Logout flow
  const handleLogout = () => {
    triggerHaptic();
    setLogoutModalVisible(true);
  };

  const cancelLogout = () => {
    triggerHaptic();
    setLogoutModalVisible(false);
  };

  const confirmLogout = () => {
    triggerHaptic();
    setLogoutModalVisible(false);
    setSettingsOpen(false);

    if (navigationRef && typeof navigationRef.isReady === 'function' && navigationRef.isReady()) {
      resetRoot('Login');
      return;
    }

    let attempts = 0;
    const maxAttempts = 10;
    const interval = setInterval(() => {
      attempts += 1;
      if (navigationRef && typeof navigationRef.isReady === 'function' && navigationRef.isReady()) {
        resetRoot('Login');
        clearInterval(interval);
      } else if (attempts >= maxAttempts) {
        clearInterval(interval);
        console.warn('[GlobalSettingsModal] resetRoot failed: navigationRef not ready after retries');
      }
    }, 100);
  };

  // Delete Account flow
  const handleDeleteAccount = () => {
    triggerHaptic();
    Alert.alert(
      'ΓÜá∩╕Å X├ôA T├ÇI KHOß║óN V─¿NH VIß╗äN',
      'H├ánh ─æß╗Öng n├áy kh├┤ng thß╗â ho├án t├íc. Mß╗ìi th├┤ng tin xe m├íy, lß╗ïch bß║úo d╞░ß╗íng, v├á ─æiß╗âm th╞░ß╗ƒng (1,200 ─æiß╗âm) sß║╜ bß╗ï x├│a v─⌐nh viß╗àn khß╗Åi hß╗ç thß╗æng Showroom Bi├¬n H├▓a.',
      [
        { text: 'Hß╗ºy', style: 'cancel' },
        {
          text: 'X├│a V─⌐nh Viß╗àn',
          style: 'destructive',
          onPress: async () => {
            try {
