  const apiKey = Constants.expoConfig?.extra?.googleMapsApiKey;

  useEffect(() => {
    if (!apiKey) {
      setError('Google Maps API key ch╞░a ─æ╞░ß╗úc cß║Ñu h├¼nh. Th├¬m EXPO_PUBLIC_GOOGLE_MAPS_WEB_API_KEY v├áo file .env');
      return;
    }

    if (!window.google) {
      const script = document.createElement('script');
      script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}&libraries=places&callback=initMapAnhEmMotor`;
      script.async = true;
      script.defer = true;
      script.onerror = () => setError('Kh├┤ng thß╗â tß║úi Google Maps script');
      document.head.appendChild(script);

      window.initMapAnhEmMotor = () => {
        console.log('Google Maps loaded');
        setIsLoaded(true);
      };
    } else {
      setIsLoaded(true);
    }

    return () => {
      polylinesRef.current.forEach(p => p.setMap(null));
      markersRef.current.forEach(m => m.setMap(null));
      if (infoWindowRef.current) {
        infoWindowRef.current.close();
      }
