      zoom: Math.round(Math.log2(360 / latitudeDelta)),
      mapTypeId: google.maps.MapTypeId[mapType.toUpperCase()] || google.maps.MapTypeId.ROADMAP,
      disableDefaultUI: false,
      zoomControl: true,
      mapTypeControl: false,
