export class MockAdminDataSource {
  async fetchDashboardStats() {
    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 300));
    return { ...inMemoryStats };
  }

  async fetchAppointments() {
    await new Promise(resolve => setTimeout(resolve, 300));
    return [...inMemoryAppointments];
  }

