    const randomImg = fakeImages[Math.floor(Math.random() * fakeImages.length)];
    if (attachedImages.length >= 3) {
      Alert.alert('Giß╗¢i hß║ín ß║únh', 'Bß║ín chß╗ë ─æ╞░ß╗úc ─æ├¡nh k├¿m tß╗æi ─æa 3 h├¼nh ß║únh minh chß╗⌐ng.');
      return;
    }
    setAttachedImages((prev) => [...prev, randomImg]);
  }, [attachedImages]);

  const handleRemoveImage = useCallback((indexToRemove) => {
    setAttachedImages((prev) => prev.filter((_, idx) => idx !== indexToRemove));
  }, []);

  // Gß╗¡i phß║ún hß╗ôi l├¬n CRM
  const handleSubmitFeedback = useCallback(() => {
    if (!feedbackText.trim()) return;

    const newTicket = {
      id: `t_${Date.now()}`,
      issueType: selectedIssue,
      content: feedbackText,
      date: new Date().toLocaleDateString('vi-VN'),
      status: 'pending',
      statusLabel: 'ΓÅ▒∩╕Å ─Éang xß╗¡ l├╜',
      reply: 'Hß╗ç thß╗æng CRM cß╗ºa AnhEmMotor ─æ├ú ghi nhß║¡n phß║ún hß╗ôi cß╗ºa bß║ín. Mß╗Öt chuy├¬n vi├¬n hß╗ù trß╗ú tß║íi chi nh├ính Bi├¬n H├▓a ─æang ─æ╞░ß╗úc ─æiß╗üu phß╗æi ─æß╗â xß╗¡ l├╜ y├¬u cß║ºu cß╗ºa bß║ín.'
    };

    setTickets((prev) => [newTicket, ...prev]);
    setFeedbackText('');
    setAttachedImages([]);
    
    Alert.alert(
      'Gß╗¡i th├ánh c├┤ng! ≡ƒÄë',
      `├¥ kiß║┐n vß╗ü vß║Ñn ─æß╗ü "${selectedIssue}" cß╗ºa bß║ín ─æ├ú ─æ╞░ß╗úc gß╗¡i trß╗▒c tiß║┐p ─æß║┐n hß╗ç thß╗æng CRM ch─âm s├│c kh├ích h├áng.`
    );
  }, [feedbackText, selectedIssue]);

  // Gß╗ìi Cß╗æ vß║Ñn trß╗▒c tiß║┐p qua sß╗æ hotline
  const handleCallAdvisor = useCallback(async () => {
    const url = 'tel:0912345678';
    try {
      const supported = await Linking.canOpenURL(url);
      if (supported) {
        await Linking.openURL(url);
      } else {
        Alert.alert('Kh├┤ng hß╗ù trß╗ú', 'Thiß║┐t bß╗ï kh├┤ng hß╗ù trß╗ú cuß╗Öc gß╗ìi trß╗▒c tiß║┐p. Hotline: 0912 345 678');
      }
    } catch {
      Alert.alert('Lß╗ùi', 'Kh├┤ng thß╗â thß╗▒c hiß╗çn cuß╗Öc gß╗ìi.');
    }
  }, []);

  // Gß╗¡i Email hß╗ù trß╗ú
  const handleEmailSupport = useCallback(async () => {
    const url = 'mailto:support@anhemmotor.vn';
    try {
      await Linking.openURL(url);
    } catch {
      Alert.alert('Lß╗ùi', 'Kh├┤ng thß╗â mß╗ƒ ß╗⌐ng dß╗Ñng Email.');
    }
  }, []);

  // Chß╗ë ─æ╞░ß╗¥ng Google Maps ─æß║┐n Showroom Bi├¬n H├▓a
  const handleNavigateMaps = useCallback(async () => {
    // Showroom AnhEmMotor Bi├¬n H├▓a: 10.9575, 106.8427
    const lat = 10.9575;
    const lng = 106.8427;
    const label = 'Showroom AnhEmMotor Bien Hoa';
    
    const url = `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
    try {
      await Linking.openURL(url);
    } catch {
      Alert.alert('Lß╗ùi', 'Kh├┤ng thß╗â khß╗ƒi chß║íy Google Maps.');
    }
  }, []);

  // Mß╗ƒ/─É├│ng Bottom Sheet chi tiß║┐t FAQ (tr╞░ß╗út tß╗½ d╞░ß╗¢i l├¬n theo quy tß║»c v├áng)
  const handleCloseFaqDetail = useCallback(() => {
    setSelectedFaq(null);
  }, []);

  // Bß║Ñm v├áo FAQ sß║╜ mß╗ƒ Bottom Sheet tr╞░ß╗út tß╗½ d╞░ß╗¢i l├¬n
  const handleToggleFaq = useCallback((id) => {
    for (const category of FAQ_CATEGORIES) {
      const found = category.items.find(item => item.id === id);
      if (found) {
        setSelectedFaq(found);
        setTimeout(() => {
          faqDetailSheetRef.current?.show();
        }, 50);
        break;
      }
    }
  }, []);

  // Kh├ích h├áng Duyß╗çt ─æ├│ng ca trong t╞░╞íng t├íc 2 chiß╗üu
  const handleApproveCloseTicket = useCallback((ticketId) => {
    setTickets(prev => prev.map(t => {
      if (t.id === ticketId) {
        return { ...t, status: 'resolved', statusLabel: 'Γ£ô ─É├ú giß║úi quyß║┐t' };
      }
      return t;
    }));
    ticketDetailSheetRef.current?.hide();
    setTimeout(() => {
      setSelectedTicket(null);
      Alert.alert('Th├ánh c├┤ng ≡ƒÄë', 'Bß║ín ─æ├ú duyß╗çt ─æ├│ng ca hß╗ù trß╗ú n├áy. Cß║úm ╞ín ├╜ kiß║┐n cß╗ºa bß║ín!');
    }, 300);
  }, []);

  return {
    selectedIssue,
    feedbackText,
    setFeedbackText,
    attachedImages,
    searchQuery,
    setSearchQuery,
    activeFaqId,
    tickets,
    selectedTicket,
    selectedFaq,
    isIssueSheetVisible,
    
    issueSheetRef,
    ticketDetailSheetRef,
    faqDetailSheetRef,
    
    handleOpenIssueSheet,
    handleSelectIssue,
    handleCloseIssueSheet,
    handleOpenTicketDetail,
    handleCloseTicketDetail,
    handleCloseFaqDetail,
    handleAttachImage,
    handleRemoveImage,
    handleSubmitFeedback,
    handleCallAdvisor,
    handleEmailSupport,
    handleNavigateMaps,
    handleToggleFaq,
    handleApproveCloseTicket
  };
};

import React, { useState, useRef } from 'react';
import { 
  StyleSheet, 
  Text, 
  View, 
  Image, 
  ScrollView, 
  TouchableOpacity, 
  Dimensions, 
  Platform,
  StatusBar
} from 'react-native';
import { useTheme } from '../../theme/Theme'; // Import useTheme
import { 
  ChevronLeft, 
  ShieldCheck, 
  Zap, 
  RotateCcw
} from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
